// Turn-based ward puzzles. No timers, canvas coordinates or client-reported wins.
// A board is generated by the server; both clients render its public state and
// send a single tile index. The server alone applies moves and checks the finish.

export type WardKind = "align" | "sequence" | "lights";

export interface WardPuzzle {
  kind: WardKind;
  seed: number;
  values: number[];  // dial orientations or 3x3 lamps
  targets: number[]; // dial targets or the rune order
  step: number;      // correct runes entered so far
  mistakes: number;
  moves: number;
}

export interface WardGameView {
  stationId: string;
  name: string;
  kind: WardKind;
  values: number[];
  targets: number[];
  step: number;
  mistakes: number;
  moves: number;
  progress: number;
}

const randomFrom = (seed: number) => {
  let x = (seed >>> 0) || 1;
  return () => {
    x ^= x << 13; x ^= x >>> 17; x ^= x << 5;
    return (x >>> 0) / 0x100000000;
  };
};

export function wardKindFor(stationKind: string): WardKind {
  if (["well", "mill", "silo"].includes(stationKind)) return "align";
  if (["pumpkins", "scarecrow", "graves"].includes(stationKind)) return "sequence";
  return "lights"; // lantern, chapel, radio
}

/** A tap flips one lamp and its orthogonal neighbours. */
export function flipLights(lamps: number[], index: number): number[] {
  const next = [...lamps];
  for (const at of [index, index - 3, index + 3, index - 1, index + 1]) {
    if (at < 0 || at >= 9) continue;
    if (Math.abs(at - index) === 1 && Math.floor(at / 3) !== Math.floor(index / 3)) continue;
    next[at] = 1 - next[at];
  }
  return next;
}

export function createWardPuzzle(stationKind: string, seed: number): WardPuzzle {
  const kind = wardKindFor(stationKind);
  const next = randomFrom(seed);
  if (kind === "align") {
    const targets = Array.from({ length: 3 }, () => Math.floor(next() * 4));
    const values = targets.map((target) => (target + 1 + Math.floor(next() * 3)) % 4);
    return { kind, seed, values, targets, step: 0, mistakes: 0, moves: 0 };
  }
  if (kind === "sequence") {
    const targets = Array.from({ length: 4 + Math.floor(next() * 2) }, () => Math.floor(next() * 4));
    return { kind, seed, values: [], targets, step: 0, mistakes: 0, moves: 0 };
  }
  // Scramble a solved board with three distinct legal moves, guaranteeing a
  // path back to all lit. The solution is not claimed by the client.
  let values = Array(9).fill(1) as number[];
  const candidates = Array.from({ length: 9 }, (_, i) => i);
  for (let i = 0; i < 3; i++) {
    const chosen = Math.floor(next() * candidates.length);
    values = flipLights(values, candidates.splice(chosen, 1)[0]);
  }
  if (values.every((v) => v === 1)) values = flipLights(values, 4);
  return { kind, seed, values, targets: [], step: 0, mistakes: 0, moves: 0 };
}

export function validWardMove(game: WardPuzzle, index: number): boolean {
  return Number.isInteger(index) && index >= 0 && index < (game.kind === "lights" ? 9 : game.kind === "align" ? 3 : 4);
}

/** Pure state transition. A wrong rune restarts only the rune sequence. */
export function applyWardMove(game: WardPuzzle, index: number): WardPuzzle {
  if (!validWardMove(game, index)) return game;
  if (game.kind === "align") {
    const values = [...game.values];
    values[index] = (values[index] + 1) % 4;
    return { ...game, values, moves: game.moves + 1 };
  }
  if (game.kind === "sequence") {
    const correct = game.targets[game.step] === index;
    return { ...game, step: correct ? game.step + 1 : 0,
      mistakes: game.mistakes + (correct ? 0 : 1), moves: game.moves + 1 };
  }
  return { ...game, values: flipLights(game.values, index), moves: game.moves + 1 };
}

export function wardSolved(game: WardPuzzle): boolean {
  if (game.kind === "align") return game.values.every((v, i) => v === game.targets[i]);
  if (game.kind === "sequence") return game.step === game.targets.length;
  return game.values.every((v) => v === 1);
}

export function wardProgress(game: WardPuzzle): number {
  if (game.kind === "align") return game.values.filter((v, i) => v === game.targets[i]).length / game.targets.length;
  if (game.kind === "sequence") return game.step / game.targets.length;
  return game.values.filter((v) => v === 1).length / 9;
}

export function wardView(stationId: string, name: string, game: WardPuzzle): WardGameView {
  return { stationId, name, kind: game.kind, values: [...game.values], targets: [...game.targets],
    step: game.step, mistakes: game.mistakes, moves: game.moves, progress: wardProgress(game) };
}
